python - <<'PY'
import limited_client as robot,numpy as np
o=robot.observe('topview');
for v in [200,208,216,224]:
 print('v',v,end=' ')
 for u in [260,270,280,290,300,310]:
  z=float(o['depth_m'][v,u]);w=o['camera_to_world']@np.r_[np.linalg.inv(o['intrinsic'])@np.array([u,v,1])*z,1];print(f'{u}:{w[2]:.2f}',end=' ')
 print()
PY

